```yaml
name: Gemini Code Review

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  review:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Gemini Code Review
        uses: actions/github-script@v6
        env:
          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}
        with:
          script: |
            const { context, github } = require('@actions/github');
            const prNumber = context.payload.pull_request.number;
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            // Fetch all files in the PR
            const files = await github.paginate(github.rest.pulls.listFiles, {
              owner,
              repo,
              pull_number: prNumber,
              per_page: 100
            });

            // Build diff content
            let diffText = '';
            for (const file of files) {
              if (file.patch) {
                diffText += `File: ${file.filename}\n${file.patch}\n\n`;
              }
            }

            if (!diffText) {
              console.log('No diff to review.');
              return;
            }

            const prompt = `Please review the following code changes and provide constructive feedback:\n\n${diffText}`;

            // Call Gemini API
            const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${process.env.GEMINI_API_KEY}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                contents: [
                  {
                    parts: [
                      { text: prompt }
                    ]
                  }
                ]
              })
            });

            if (!response.ok) {
              const errorText = await response.text();
              console.error('Gemini API error:', errorText);
              throw new Error('Gemini API request failed');
            }

            const data = await response.json();
            const reviewText = data.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || 'No review generated.';

            // Post review comment
            await github.rest.pulls.createReview({
              owner,
              repo,
              pull_number: prNumber,
              body: reviewText,
              event: 'COMMENT'
            });

            console.log('Review posted successfully.');
